    });
    if (!response.ok) {
      const result = await response.json();
      taskError.textContent = result.error || 'Unable to create task';
      taskError.hidden = false;
      return;
    }
    taskInput.value = '';
    await renderTasks();
  });
  await renderTasks();
}

